"""Resolve evidence into final EUR prices. Missing information stays explicit."""
from __future__ import annotations

from collections import defaultdict
from decimal import Decimal, localcontext

from .business_rules import (
    ZERO,
    Unresolved,
    allocate,
    effective_position,
    engineering,
    exact_match,
    latest,
    marginal_bonus,
    money,
    pieces,
    price_condition,
    remaining_qa,
    valid_on,
)
from .contracts import PricingResult, ResolvedTender


def one(items, message):
    if len(items) != 1:
        raise Unresolved(message)
    return items[0]


def calculate(ledger, allow_partial=False) -> PricingResult:
    with localcontext() as ctx:
        ctx.prec = 40
        try:
            return _calculate(ledger, allow_partial)
        except (Unresolved, ArithmeticError, ValueError) as exc:
            return PricingResult(answer=None, unresolved={"order": [str(exc)]})


def _calculate(ledger, allow_partial):
    tender = one(ledger.all("tender"), "Need one tender record")
    date = tender.scenario_date
    if len(tender.position_ids) != len(set(tender.position_ids)):
        raise Unresolved("Duplicate tender positions")
    if not tender.quantities_complete or not tender.qa_complete:
        raise Unresolved("Tender quantities and applicable Q&A must be completely investigated")
    revision = one([x for x in ledger.all("revision") if x.current and x.full],
                   "Need one governing current full specification revision")
    answers = remaining_qa(ledger.all("qa"), date)

    def mail(kind, local_part, subject, required=True, **scope):
        result = latest(ledger.all(kind), date=date, reference=tender.reference,
                        sender=local_part + "@" + tender.mailbox_domain, subject=subject, **scope)
        if result is None and required:
            raise Unresolved(f"Missing applicable {subject} for {scope}")
        return result

    resolved = ResolvedTender(reference=tender.reference, decision="unresolved")
    lines, issues, missing = {}, defaultdict(list), []
    for pos in tender.position_ids:
        try:
            original = one([x for x in ledger.all("position") if x.position == pos], f"Missing position {pos}")
            position = effective_position(original, answers)
            req = one([x for x in ledger.all("requirement") if x.requirement_id == position.requirement_id
                       and x.revision == revision.revision], f"Missing current requirement for {pos}")
            technical = mail("technical", "technik", "Technikfreigabe", required=req.stroke_mode == "usable",
                             revision=revision.revision, requirement_id=req.requirement_id)
            attrs = engineering(req, answers, technical.reserve_per_end_mm if technical else None)
            quantity = pieces(position, req)
            search = one([x for x in ledger.all("search") if x.requirement_id == req.requirement_id
                          and x.revision == revision.revision and x.catalogue_group == req.catalogue_group
                          and x.complete], f"Need completed narrow ERP search for {pos}")
            candidates = [x for x in ledger.all("material") if x.material_number in search.candidate_materials]
            if len({x.material_number for x in candidates}) != len(set(search.candidate_materials)):
                raise Unresolved("Some ERP candidates have not been inspected")
            matches = [x for x in candidates if x.catalogue_group == req.catalogue_group and exact_match(x, attrs)]
            if not matches:
                missing.append(pos)
                continue
            material = one(matches, f"Multiple exact active matches for {pos}")
            lines[pos] = {"position": position, "requirement": req, "material": material, "quantity": quantity,
                          "base": None, "mass": None, "setup": material.ordinary_setup_eur,
                          "shared": ZERO, "packaging": ZERO, "bonus": ZERO, "scope": "base"}
        except (Unresolved, ValueError) as exc:
            issues[pos].append(str(exc))

    if missing:
        approval = mail("discount", "leitung", "", required=False)
        discount = approval.percent if approval and approval.minimum_base_goods_eur is None else ZERO
        resolved.decision, resolved.missing_materials = "no_bid", missing
        return PricingResult(answer={"tender_reference": tender.reference, "decision": "no_bid", "currency": "EUR",
                                      "discount_percent": discount, "positions": [], "total_net": ZERO},
                             audit=[{"rule": "no_active_exact_match", "positions": missing}])

    demand = defaultdict(int)
    for line in lines.values():
        demand[line["material"].material_number] += line["quantity"]
    # Every known line can depend on an unknown line's material and quantity.
    if len(lines) != len(tender.position_ids):
        raise Unresolved("Resolve quantities and material matches for ALL positions before pooled stock/order pricing")

    for pos, line in lines.items():
        try:
            material, qty, position = line["material"], line["quantity"], line["position"]
            condition, scale = price_condition(ledger.all("price"), material.material_number, qty, date)
            rate = Decimal(1)
            if condition.currency.upper() != "EUR":
                if not condition.fx_key:
                    raise Unresolved("Foreign currency price is missing its FX key")
                fx = mail("fx", "finanzen", "Devisenfixing", key=condition.fx_key, currency=condition.currency)
                if not valid_on(fx, date):
                    raise Unresolved("Latest FX fixing is outside its validity window")
                rate = fx.eur_per_unit
            line["base"] = money(scale.amount / condition.price_unit * rate)
            if material.surcharge_kind == "none":
                line["mass"] = ZERO
            else:
                if material.mass_kg is None:
                    raise Unresolved("Missing surcharge mass")
                if material.surcharge_kind == "fixed_per_kg":
                    metal_rate = material.fixed_rate_eur_per_kg
                else:
                    index = mail("metal_index", "kalkulation", "Preisindizes", key=material.metal_index_key)
                    metal_rate = one([r for r in index.rates if valid_on(r, date)],
                                     "Need one on-date metal index rate").eur_per_kg
                if metal_rate is None:
                    raise Unresolved("Missing mass surcharge rate")
                line["mass"] = material.mass_kg * metal_rate
            if position.commercial_key:
                line["scope"] = mail("commercial", "kalkulation", "Konditionsregeln",
                                     key=position.commercial_key).discount_scope
            if position.packaging_key:
                tariff = mail("packaging", "logistik", "Verpackungstarife", key=position.packaging_key)
                if material.carton_size is None:
                    raise Unresolved("Missing pieces per carton")
                cartons = (qty + material.carton_size - 1) // material.carton_size
                line["packaging"] = cartons * tariff.carton_fee_eur
            pooled = demand[material.material_number]
            lead = material.stock_weeks if material.stock >= pooled else material.production_weeks
            if position.commitment_key:
                commitment = mail("commitment", "logistik", "Terminfreigabe", key=position.commitment_key)
                if commitment.material_number == material.material_number and pooled <= commitment.maximum_quantity:
                    lead = commitment.lead_time_weeks
            line["lead"] = lead
        except (Unresolved, ValueError) as exc:
            issues[pos].append(str(exc))

    if not tender.approvals_complete or not tender.commercial_rules_complete or not tender.bonus_rules_complete:
        raise Unresolved("Complete approval, commercial and project-bonus investigation before pricing")
    approval = mail("discount", "leitung", "", required=False)
    if approval and approval.minimum_base_goods_eur is not None and any(x["base"] is None for x in lines.values()):
        raise Unresolved("Conditional discount needs the whole tender's undiscounted base goods")
    goods = {pos: line["quantity"] * line["base"] for pos, line in lines.items() if line["base"] is not None}
    threshold_total = money(sum(goods.values(), ZERO))
    percent = approval.percent if approval else ZERO
    if approval and approval.minimum_base_goods_eur is not None and threshold_total < approval.minimum_base_goods_eur:
        percent = ZERO

    pool_members = defaultdict(list)
    for pos, line in lines.items():
        for key in line["position"].pool_keys:
            pool_members[key].append(pos)
    for key, members in pool_members.items():
        try:
            pool = mail("pool", "kalkulation", "RÃ¼stpools", key=key)
            if any(lines[p]["material"].allocation_mass_kg is None for p in members):
                raise Unresolved("Missing allocation mass (distinct from surcharge mass)")
            allocation = allocate(pool.fee_eur, {p: lines[p]["quantity"] * lines[p]["material"].allocation_mass_kg
                                                for p in members}, pool.allocation)
            for pos, amount in allocation.items():
                lines[pos]["shared"] += amount
        except (Unresolved, ValueError) as exc:
            for pos in members:
                issues[pos].append(str(exc))

    bonus = mail("bonus", "finanzen", "Projektbonus", required=False)
    if bonus:
        if not set(bonus.eligible_positions) <= set(tender.position_ids):
            raise Unresolved("Bonus includes an unknown tender position")
        if any(pos not in goods for pos in bonus.eligible_positions):
            for pos in bonus.eligible_positions:
                issues[pos].append("Whole eligible goods total is needed for project bonus")
        else:
            eligible = {pos: goods[pos] for pos in bonus.eligible_positions}
            credit = marginal_bonus(sum(eligible.values(), ZERO), bonus.bands)
            for pos, amount in allocate(credit, eligible).items():
                lines[pos]["bonus"] = amount

    answer_lines, audit = [], []
    for pos, line in lines.items():
        if issues[pos]:
            continue
        qty, base, mass = line["quantity"], line["base"], line["mass"]
        factor = 1 - percent / 100
        discounted_base = base * factor if line["scope"] != "neither" else base
        discounted_mass = mass * factor if line["scope"] == "base_and_mass" else mass
        fees = line["setup"] + line["shared"] + line["packaging"] - line["bonus"]
        unit = money(discounted_base + discounted_mass + fees / qty)
        if unit < 0:
            issues[pos].append("Negative unit price; reconcile source rules")
            continue
        result = {"position": pos, "material_number": line["material"].material_number, "quantity": qty,
                  "unit_price": unit, "lead_time_weeks": line["lead"], "base_unit_price": base,
                  "surcharge_per_unit": money(mass + (line["setup"] + line["shared"]) / qty),
                  "packaging_per_unit": money(line["packaging"] / qty), "rebate_total": line["bonus"]}
        answer_lines.append(result)
        audit.append({"position": pos, "quantity": qty, "base": base, "mass": mass,
                      "ordinary_setup": line["setup"], "shared_setup": line["shared"],
                      "carton_cost": line["packaging"], "bonus": line["bonus"], "discount_scope": line["scope"],
                      "unit_price": unit, "material_evidence": line["material"].evidence})
    issues = {key: value for key, value in issues.items() if value}
    omitted = sorted(set(tender.position_ids) - {x["position"] for x in answer_lines})
    if omitted and not allow_partial or not answer_lines:
        return PricingResult(answer=None, omitted=omitted, unresolved=issues, audit=audit)
    answer = {"tender_reference": tender.reference, "decision": "bid", "currency": "EUR",
              "discount_percent": percent, "positions": answer_lines,
              "total_net": money(sum((x["quantity"] * x["unit_price"] for x in answer_lines), ZERO))}
    if omitted:
        answer["notes"] = "Unfinished positions explicitly omitted: " + ", ".join(omitted)
    audit.append({"rule": "approved_discount", "base_goods_threshold_total": threshold_total,
                  "percent": percent, "approval_evidence": approval.evidence if approval else tender.evidence})
    return PricingResult(answer=answer, omitted=omitted, unresolved=issues, audit=audit)
"""Deterministic scope, precedence and matching rules; no browser knowledge."""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import ROUND_HALF_UP, Decimal
from email.utils import parseaddr

from .contracts import Engineering

CENT = Decimal("0.01")
ZERO = Decimal(0)


class Unresolved(ValueError):
    pass


def money(value: Decimal) -> Decimal:
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def aware(value: datetime) -> datetime:
    if value.tzinfo is None:
        raise Unresolved("A date is missing its source timezone")
    return value.astimezone(timezone.utc)


def valid_on(item, date: datetime) -> bool:
    return ((item.valid_from is None or aware(item.valid_from) <= aware(date)) and
            (item.valid_to is None or aware(date) <= aware(item.valid_to)))


def latest(items, *, date: datetime, reference: str, sender: str, subject: str, **scope):
    applicable = [x for x in items if x.reference == reference and
                  parseaddr(x.sender)[1].casefold() == sender.casefold() and
                  subject.casefold() in x.subject.casefold() and aware(x.sent_at) <= aware(date) and
                  all(getattr(x, key) == value for key, value in scope.items())]
    if not applicable:
        return None
    applicable.sort(key=lambda x: aware(x.sent_at), reverse=True)
    if len(applicable) > 1 and applicable[0].sent_at == applicable[1].sent_at:
        a, b = (x.model_dump(exclude={"id", "evidence"}) for x in applicable[:2])
        if a != b:
            raise Unresolved("Conflicting equally recent authorized records")
    return applicable[0]


def remaining_qa(answers, date: datetime):
    dated = [x for x in answers if aware(x.issued_at) <= aware(date)]
    withdrawn = {target for x in dated for target in x.withdraws}
    return sorted([x for x in dated if x.id not in withdrawn], key=lambda x: (aware(x.issued_at), x.id))


def effective_position(position, answers):
    updates = {}
    for answer in answers:
        if answer.position != position.position:
            continue
        for key in ("quantity", "commercial_key", "packaging_key", "commitment_key", "pool_keys"):
            value = getattr(answer, key)
            if value is not None:
                updates[key] = value
    return position.model_copy(update=updates)


def engineering(requirement, answers, reserve: Decimal | None):
    attributes = requirement.attributes.model_dump()
    for answer in answers:
        if answer.revision == requirement.revision and answer.requirement_id == requirement.requirement_id:
            unknown = set(answer.amendments) - set(attributes)
            if unknown:
                raise Unresolved(f"Unsupported technical amendments: {sorted(unknown)}")
            attributes.update(answer.amendments)
    result = Engineering.model_validate(attributes)
    if requirement.stroke_mode == "usable":
        if reserve is None:
            raise Unresolved("Missing revision-specific per-end stroke reserve")
        result = result.model_copy(update={"stroke_mm": result.stroke_mm + 2 * reserve})
    return result


def pieces(position, requirement) -> int:
    if position.unit == "pieces":
        return position.quantity
    if requirement.pieces_per_set is None:
        raise Unresolved("Missing pieces per set in the governing revision")
    return position.quantity * requirement.pieces_per_set


def exact_match(material, required: Engineering) -> bool:
    return material.active and material.attributes == required


def price_condition(conditions, material_number, quantity: int, date: datetime):
    applicable = [x for x in conditions if x.material_number == material_number and valid_on(x, date)]
    if len(applicable) != 1:
        raise Unresolved(f"Need one unambiguous on-date price condition for {material_number}")
    condition = applicable[0]
    scales = [x for x in condition.scales if x.min_quantity <= quantity]
    if not scales:
        raise Unresolved("No applicable price scale")
    maximum = max(x.min_quantity for x in scales)
    best = [x for x in scales if x.min_quantity == maximum]
    if len({x.amount for x in best}) != 1:
        raise Unresolved("Conflicting quantity scales")
    return condition, best[0]


def allocate(total: Decimal, weights: dict[str, Decimal], rule="largest_remainder") -> dict[str, Decimal]:
    from decimal import ROUND_DOWN

    total = money(total)
    if total < 0 or any(value < 0 for value in weights.values()):
        raise Unresolved("Negative allocation")
    if not weights:
        if total:
            raise Unresolved("Nonzero fee has no allocation members")
        return {}
    keys = sorted(weights)
    weight = sum(weights.values(), ZERO)
    if not weight:
        if total:
            raise Unresolved("Nonzero fee has zero allocation weight")
        return dict.fromkeys(keys, ZERO)
    cents = int(total * 100)
    raw = {key: Decimal(cents) * weights[key] / weight for key in keys}
    mode = ROUND_HALF_UP if rule == "half_up_adjust_last" else ROUND_DOWN
    shares = {key: int(raw[key].to_integral_value(rounding=mode)) for key in keys}
    remainder = cents - sum(shares.values())
    if rule == "largest_remainder":
        order = sorted(keys, key=lambda key: (-(raw[key] - shares[key]), key))
        for key in order[:remainder]:
            shares[key] += 1
    elif rule in {"half_up_adjust_last", "floor_remainder_last"}:
        shares[keys[-1]] += remainder
    else:
        raise Unresolved(f"Unsupported cent-allocation rule: {rule}")
    if any(value < 0 for value in shares.values()) or sum(shares.values()) != cents:
        raise Unresolved("Invalid cent allocation")
    return {key: Decimal(value) / 100 for key, value in shares.items()}


def marginal_bonus(goods: Decimal, bands) -> Decimal:
    lower, credit = ZERO, ZERO
    for index, band in enumerate(bands):
        upper = band.upper_eur
        if upper is None and index != len(bands) - 1:
            raise Unresolved("Unbounded bonus band must be last")
        if upper is not None and upper <= lower:
            raise Unresolved("Bonus bands must have increasing cumulative upper boundaries")
        part = max(ZERO, min(goods, upper if upper is not None else goods) - lower)
        credit += part * band.percent / 100
        if upper is None:
            break
        lower = upper
    return money(credit)
from __future__ import annotations

import re
import time
from decimal import Decimal

import httpx
import jsonschema
import simplejson

from .contracts import SubmissionState
from .runtime import USER_AGENT


def validate_answer(answer: dict, schema: dict):
    jsonschema.Draft202012Validator(schema).validate(answer)
    payload = simplejson.dumps(answer, use_decimal=True, ensure_ascii=False).encode()
    if len(payload) > 65536:
        raise ValueError("Answer exceeds platform size limit")
    positions = answer["positions"]
    if len({x["position"] for x in positions}) != len(positions):
        raise ValueError("Duplicate positions")
    if answer["decision"] == "no_bid" and (positions or Decimal(str(answer["total_net"])) != 0):
        raise ValueError("no_bid requires no positions and a zero total")
    total = sum((Decimal(str(x["unit_price"])) * x["quantity"] for x in positions), Decimal(0))
    if total != Decimal(str(answer["total_net"])):
        raise ValueError("Total must equal quantities times final rounded unit prices")
    return payload


class Submission:
    def __init__(self, run, browser, telemetry):
        self.run, self.browser, self.telemetry = run, browser, telemetry
        self.state = SubmissionState.DRAFT
        self.result = None
        self.receipt = None
        self.signing_attempted_at = None

    def transition(self, state):
        self.state = state
        self.telemetry.emit("submission_state", submission=state.value)

    def prepare(self, result):
        if not result.answer:
            raise ValueError("No verified answer ready; resolve calculation issues")
        validate_answer(result.answer, self.run.answer_schema)
        self.result = result
        self.transition(SubmissionState.VALIDATED)
        self.telemetry.emit("submission_started", answer=result.answer, omitted=result.omitted)
        return {"answer": result.answer, "omitted": result.omitted,
                "instruction": "Map these values to current form controls. Explicitly omit listed positions; sign and verify receipt."}

    def answer_value(self, path):
        if self.result is None:
            raise ValueError("Prepare a verified answer first")
        value = self.result.answer
        for part in path.split("."):
            value = value[int(part)] if isinstance(value, list) else value[part]
        if isinstance(value, (dict, list)):
            raise ValueError("Answer path must select one field")
        return value

    async def fill(self, fields):
        if self.state not in {SubmissionState.VALIDATED, SubmissionState.TAN_REQUESTED}:
            raise ValueError("Answer not ready for entry")
        for field in fields:
            value = self.answer_value(field["path"])
            if isinstance(value, Decimal):
                value = format(value, "f")
            else:
                value = str(value)
            if field.get("format") == "de":
                value = value.replace(".", ",")
            await self.browser.act("fill", {"ref": field["ref"], "text": value})
        return {"filled": len(fields)}

    async def request_tan(self, args):
        if self.result is None:
            raise ValueError("Prepare a validated answer before requesting TAN")
        self.browser.latest_tan = None
        self.browser.tan_captured_at = None
        self.browser.tan_requested_at = time.monotonic()
        self.browser.tan_request_observation = self.browser.observation_number
        await self.browser.act("click", {"ref": args["ref"]})
        self.transition(SubmissionState.TAN_REQUESTED)
        self.telemetry.emit("tan_requested")
        return {"requested": True, "instruction": "Read the newest matching signing mail; prior TANs are invalid."}

    async def sign(self, args):
        if self.state != SubmissionState.TAN_REQUESTED or not self.browser.latest_tan:
            raise ValueError("Signing requires a fresh requested and captured TAN")
        if time.monotonic() - self.browser.tan_captured_at > 240:
            raise ValueError("TAN may be expired; request a fresh TAN")
        if not args.get("reviewed") or not args.get("omissions_confirmed"):
            raise ValueError("Review the portal values and explicit omissions before final signing")
        self.signing_attempted_at = time.monotonic()
        self.transition(SubmissionState.SIGNING_ATTEMPTED)
        await self.browser.act("click", {"ref": args["ref"]})
        return {"attempted": True, "instruction": "Handle the confirmation dialog, then inspect the receipt. Do not repeat an uncertain signing action."}

    def accept_receipt(self, observation, args):
        if self.state != SubmissionState.SIGNING_ATTEMPTED:
            raise ValueError("No signing attempt to verify")
        if not self.result:
            raise ValueError("No prepared answer")
        excerpt = args["excerpt"]
        if excerpt not in observation.text:
            raise ValueError("Receipt excerpt must be present in the observed page")
        receipt_id = args.get("receipt_id", "")
        if not receipt_id or receipt_id not in observation.text:
            raise ValueError("Read the visible receipt/confirmation identifier")
        if not re.search(r"(?i)(eingegangen|eingereicht|Ã¼bermittelt|abgegeben|erfolgreich|bestÃ¤tigung|accepted|received|receipt|acknowledged)", excerpt):
            raise ValueError("Receipt does not state completed acceptance")
        if self.result.answer["tender_reference"] not in observation.text:
            raise ValueError("Receipt must identify the submitted tender")
        self.receipt = {"id": receipt_id, "excerpt": excerpt, "url": observation.url,
                        "observation": observation.id, "reference": self.result.answer["tender_reference"]}
        local = self.run.kind == "scouting"
        self.transition(SubmissionState.SCOUTING_ACKNOWLEDGED if local else SubmissionState.ACCEPTED)
        self.telemetry.emit("scouting_acknowledged" if local else "submission_accepted", receipt=self.receipt)
        self.telemetry.artifact("receipt.json", self.receipt)
        return self.receipt

    async def api_submit(self, token):
        if self.run.submission.kind != "api":
            raise ValueError("This run requires the website signing workflow")
        if self.result is None or not token:
            raise ValueError("A validated answer and a live run token are required")
        payload = validate_answer(self.result.answer, self.run.answer_schema)
        async with httpx.AsyncClient(timeout=20, headers={"User-Agent": USER_AGENT, "x-api-key": token,
                                                        "Content-Type": "application/json"}) as client:
            response = await client.post(self.run.submission.url, content=payload)
        if response.status_code == 400:
            return {"validation_issues": response.json()}
        if response.status_code != 202:
            raise RuntimeError(f"Submission returned HTTP {response.status_code}")
        self.receipt = response.json()
        self.transition(SubmissionState.ACCEPTED)
        self.telemetry.emit("submission_accepted", receipt=self.receipt)
        self.telemetry.artifact("receipt.json", self.receipt)
        return self.receipt

