            entry = archive.getinfo(member)
            if entry.flag_bits & 1 or entry.file_size > MAX_DOCUMENT_BYTES:
                raise ValueError("Encrypted or oversized ZIP member")
            return read_document(archive.read(entry), member, page=page)
